// spec: specs/businessdetail-gallery.md (1.1–1.5) · кейсы: .qa/tests/businessdetail-gallery/GALLERY-01..05.md
// #d31f3b (PR #204) заменил #c49537: окно фиксированное (десктоп 800×400, телефон 16:9), картинка cover по центру.
// seed: tests/seed.spec.ts (гость) · прод, только просмотр: SW выкл, не-GET блокируются, cookie «חיוניים בלבד», PWA снузено.
// Устройства: @desktop (1440×900) и @mobile (iPhone 13 Mini WebKit + Pixel 7 Chromium) — отдельными тестами.
// Имя файла историческое (раньше — окно по пропорции картинки); оставлено, чтобы не терять историю прогонов.
import { test, expect } from '@playwright/test';
import {
  prepare, openListing, readWindow, settledImage, expectCovered, expectFixedFrame, nextArrow, fullscreenButton,
  LISTINGS, LOAD, PX_TOL, windowLocator,
} from './gallery.helpers';

test.use({ serviceWorkers: 'block' });

const DEVICES = ['@desktop', '@mobile'] as const;

for (const dev of DEVICES) {
  test.describe(`Галерея страницы объявления ${dev}`, () => {
    test.beforeEach(async ({ page }) => {
      await prepare(page);
    });

    for (const kind of ['vertical', 'square'] as const) {
      const L = LISTINGS[kind];
      const title = kind === 'vertical' ? 'вертикальная картинка' : 'квадратная картинка';
      test(`${title} — фиксированное окно, cover по центру, без полос #d31f3b ${dev} @prod-safe`, async ({ page }) => {
        await openListing(page, L.id);
        const s = await settledImage(page, kind);
        test.skip(
          s.img!.nat[0] !== L.nat[0] || s.img!.nat[1] !== L.nat[1],
          `первая картинка объявления сменилась (${s.img!.nat.join('×')} вместо ${L.nat.join('×')}) — данные прода`,
        );
        expectFixedFrame(s, dev, kind);
        expectCovered(s, kind);
      });
    }

    test(`листание — размер окна одинаковый, каждая картинка cover #d31f3b ${dev} @prod-safe`, async ({ page }) => {
      await openListing(page, LISTINGS.mixed.id);
      let s = await settledImage(page, 'картинка 1');
      const arrow = nextArrow(page);
      test.skip(!(await arrow.count()), 'в объявлении «משתלה» больше нет нескольких картинок — данные прода');
      const sizes: Array<[number, number]> = [];
      for (let i = 1; i <= LISTINGS.mixed.count; i++) {
        if (i > 1) {
          const prev = s.img!.src;
          await arrow.click();
          s = await settledImage(page, `картинка ${i}`, prev);
        }
        const label = `картинка ${i} (${s.img!.nat.join('×')})`;
        expectFixedFrame(s, dev, label);
        expectCovered(s, label);
        sizes.push([s.win.w, s.win.h]);
      }
      const [w0, h0] = sizes[0];
      const list = sizes.map(([w, h]) => `${w.toFixed(1)}×${h.toFixed(1)}`).join(' / ');
      expect(sizes.every(([w, h]) => Math.abs(w - w0) <= PX_TOL && Math.abs(h - h0) <= PX_TOL), `размер окна одинаковый на всех картинках: ${list}`).toBe(true);
    });

    test(`видео — то же широкое окно, без кнопки полноэкранного просмотра #c49537 #d31f3b ${dev} @prod-safe`, async ({ page }) => {
      await openListing(page, LISTINGS.video.id);
      await expect(windowLocator(page).locator('video'), 'видео в окне галереи').toBeVisible(LOAD);
      const s = await readWindow(page);
      test.skip(!s.video, 'первый слайд объявления больше не видео — данные прода');
      expect(s.win.w / s.win.h, `окно видео широкое ${s.win.w.toFixed(0)}×${s.win.h.toFixed(0)} (≥16:9)`).toBeGreaterThanOrEqual((16 / 9) * 0.98);
      expect(s.win.h, 'высота рамки видео ≤ 400 px').toBeLessThanOrEqual(400 + 1);
      expect(s.video!.w, 'видео во всю ширину окна').toBeGreaterThanOrEqual(s.win.w - 1);
      await expect(fullscreenButton(page), 'на слайде с видео нет кнопки «הצגת התמונה במסך מלא» (лайтбокс — только картинки)').toHaveCount(0);
    });
  });
}

test.describe('Галерея страницы объявления — регресс #154394 @desktop', () => {
  test.beforeEach(async ({ page }) => {
    await prepare(page);
  });

  test(`листание не прокручивает страницу (scrollY 0 и 320) #c49537 #154394 #d31f3b @desktop @prod-safe`, async ({ page }) => {
    await openListing(page, LISTINGS.mixed.id);
    let s = await settledImage(page, 'картинка 1');
    const arrow = nextArrow(page);
    test.skip(!(await arrow.count()), 'в объявлении «משתלה» больше нет нескольких картинок — данные прода');

    // scrollY = 0 — обычное нажатие.
    await arrow.click();
    s = await settledImage(page, 'после листания на scrollY 0', s.img!.src);
    expect(s.scrollY, 'scrollY 0 не изменился').toBeLessThanOrEqual(1);

    // scrollY = 320: стрелка под липкой шапкой 125 px (известная находка) — нажатие самой кнопки через JS (click()),
    // проверяем, что обработчик листания не двигает страницу.
    await page.evaluate(() => window.scrollTo(0, 320));
    await expect.poll(() => page.evaluate(() => window.scrollY), { message: 'страница прокручена на 320' }).toBe(320);
    await arrow.evaluate((b: HTMLElement) => b.click());
    s = await settledImage(page, 'после листания на scrollY 320', s.img!.src);
    expect(Math.abs(s.scrollY - 320), `scrollY 320 не изменился (сейчас ${s.scrollY})`).toBeLessThanOrEqual(1);
  });
});
